import{_ as h,o as t,c,a2 as i}from"./chunks/framework.CqpfiAoK.js";const d=JSON.parse('{"title":"Nguyên tắc Đạo đức Song hồn","description":"","frontmatter":{},"headers":[],"relativePath":"vi/58-双魂伦理准则.md","filePath":"vi/58-双魂伦理准则.md"}'),a={name:"vi/58-双魂伦理准则.md"};function g(u,n,o,l,y,r){return t(),c("div",null,[...n[0]||(n[0]=[i('<h1 id="nguyen-tac-đao-đuc-song-hon" tabindex="-1">Nguyên tắc Đạo đức Song hồn <a class="header-anchor" href="#nguyen-tac-đao-đuc-song-hon" aria-label="Permalink to &quot;Nguyên tắc Đạo đức Song hồn&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>58</td></tr><tr><td>Mô-đun</td><td>Chủng tộc và Hình thái sự sống</td></tr><tr><td>Từ khóa cốt lõi</td><td>Đạo đức song hồn, quyền nhân cách, phẩm giá linh hồn, cân bằng lợi ích, xét duyệt đạo đức</td></tr></tbody></table><h2 id="_1-đat-ra-van-đe-đao-đuc-song-hon" tabindex="-1">1. Đặt ra Vấn đề Đạo đức Song hồn <a class="header-anchor" href="#_1-đat-ra-van-đe-đao-đuc-song-hon" aria-label="Permalink to &quot;1. Đặt ra Vấn đề Đạo đức Song hồn&quot;">​</a></h2><p>Vấn đề đạo đức song hồn là vấn đề đạo đức cơ bản mà nền văn minh Cộng sinh Mỏ neo phải trả lời khi đối mặt với cơ thể thay thế bóng tối (xem chi tiết &quot;57-Nguồn gốc và Bản chất của Cơ thể Thay thế Bóng tối&quot;). Khi trong một cơ thể tồn tại hai linh hồn độc lập — linh hồn chủ nhà ban đầu và linh hồn thay thế bóng tối — một loạt các vấn đề đạo đức sâu sắc nảy sinh:</p><ul><li>Cả hai linh hồn có đều có quyền nhân cách độc lập không?</li><li>Quyền của linh hồn chủ nhà ban đầu có được ưu tiên hơn linh hồn thay thế bóng tối không?</li><li>Việc tiêu diệt linh hồn thay thế bóng tối để bảo vệ linh hồn chủ nhà ban đầu có đạo đức không?</li><li>Khi lợi ích của hai linh hồn xung đột, nên cân bằng như thế nào?</li><li>Xã hội có nghĩa vụ đầu tư nguồn lực để cứu linh hồn chủ nhà ban đầu đã bị thay thế bởi bóng tối không?</li><li>Linh hồn thay thế bóng tối có &quot;quyền sống&quot; không?</li></ul><p>Những vấn đề này không có câu trả lời đơn giản, cần thiết lập các nguyên tắc đạo đức có hệ thống để hướng dẫn thực tiễn. &quot;Nguyên tắc Đạo đức Song hồn&quot; chính là tài liệu quy phạm được ban hành để đáp ứng những vấn đề này, là cơ sở đạo đức cho việc nhận dạng, điều trị và xử lý cơ thể thay thế bóng tối.</p><h2 id="_2-cac-nguyen-tac-co-ban-cua-đao-đuc-song-hon" tabindex="-1">2. Các Nguyên tắc Cơ bản của Đạo đức Song hồn <a class="header-anchor" href="#_2-cac-nguyen-tac-co-ban-cua-đao-đuc-song-hon" aria-label="Permalink to &quot;2. Các Nguyên tắc Cơ bản của Đạo đức Song hồn&quot;">​</a></h2><p>Nguyên tắc đạo đức song hồn thiết lập sáu nguyên tắc cơ bản sau làm nền tảng giá trị để xử lý vấn đề song hồn:</p><table tabindex="0"><thead><tr><th>Nguyên tắc</th><th>Nội hàm</th></tr></thead><tbody><tr><td>Nguyên tắc phẩm giá linh hồn</td><td>Mỗi linh hồn có ý thức độc lập đều hưởng thụ phẩm giá bẩm sinh, không được tùy tiện tiêu diệt hoặc nô dịch</td></tr><tr><td>Nguyên tắc ưu tiên chủ nhà ban đầu</td><td>Trong xung đột song hồn, quyền hợp pháp của linh hồn chủ nhà ban đầu được ưu tiên hơn linh hồn thay thế bóng tối, vì chủ nhà ban đầu là chủ sở hữu hợp pháp của cơ thể</td></tr><tr><td>Nguyên tắc thiệt hại tối thiểu</td><td>Khi xử lý vấn đề song hồn, nên chọn phương án gây thiệt hại nhỏ nhất cho tất cả các bên liên quan, càng nhiều càng tốt tránh tiêu diệt linh hồn</td></tr><tr><td>Nguyên tắc tỷ lệ</td><td>Các biện pháp được áp dụng phải phù hợp với mức độ rủi ro của cơ thể song hồn, cấm xử lý quá mức</td></tr><tr><td>Nguyên tắc đồng ý có thông tin</td><td>Trong điều kiện linh hồn chủ nhà ban đầu có thể bày tỏ ý chí, các quyết định quan trọng liên quan đến cơ thể và linh hồn của chủ nhà ban đầu phải được sự đồng ý của chủ nhà ban đầu</td></tr><tr><td>Nguyên tắc cố gắng cứu vớt tối đa</td><td>Xã hội có nghĩa vụ trong giới hạn hợp lý cố gắng cứu vớt linh hồn chủ nhà ban đầu đã bị thay thế bởi bóng tối, không được dễ dàng từ bỏ</td></tr></tbody></table><h2 id="_3-cong-nhan-quyen-nhan-cach-cua-song-hon" tabindex="-1">3. Công nhận Quyền Nhân cách của Song hồn <a class="header-anchor" href="#_3-cong-nhan-quyen-nhan-cach-cua-song-hon" aria-label="Permalink to &quot;3. Công nhận Quyền Nhân cách của Song hồn&quot;">​</a></h2><p>Vấn đề hàng đầu của đạo đức song hồn là công nhận quyền nhân cách của hai linh hồn. Nguyên tắc này thiết lập các quy tắc công nhận sau:</p><h3 id="_1-quyen-nhan-cach-cua-linh-hon-chu-nha-ban-đau" tabindex="-1">(1) Quyền Nhân cách của Linh hồn Chủ nhà Ban đầu <a class="header-anchor" href="#_1-quyen-nhan-cach-cua-linh-hon-chu-nha-ban-đau" aria-label="Permalink to &quot;(1) Quyền Nhân cách của Linh hồn Chủ nhà Ban đầu&quot;">​</a></h3><p>Linh hồn chủ nhà ban đầu là chủ sở hữu hợp pháp của cơ thể, quyền nhân cách của nó được công nhận và bảo vệ đầy đủ:</p><ol><li>Linh hồn chủ nhà ban đầu hưởng thụ tất cả các quyền cơ bản do hiến pháp cộng sinh ban hành, bao gồm quyền sống, quyền cơ thể, quyền sức khỏe, quyền phẩm giá nhân cách, v.v.</li><li>Linh hồn chủ nhà ban đầu có quyền quyết định cuối cùng đối với cơ thể của mình, trong điều kiện có thể bày tỏ ý chí, bất kỳ xử lý quan trọng nào liên quan đến cơ thể phải được sự đồng ý của chủ nhà ban đầu.</li><li>Các quyền lợi hợp pháp của linh hồn chủ nhà ban đầu như quyền tài sản, quyền danh tính, quan hệ xã hội, v.v. được pháp luật bảo vệ, không bị mất đi do bị thay thế bởi bóng tối.</li><li>Linh hồn chủ nhà ban đầu có quyền nhận được sự cứu trợ và hỗ trợ của xã hội, bao gồm điều trị thanh lọc, hỗ trợ pháp lý, tư vấn tâm lý, v.v.</li><li>Ngay cả khi linh hồn chủ nhà ban đầu bị đàn áp sâu sắc, quyền nhân cách của nó vẫn tồn tại, không được tuyên bố chết hoặc tước quyền.</li></ol><h3 id="_2-quyen-nhan-cach-cua-linh-hon-thay-the-bong-toi" tabindex="-1">(2) Quyền Nhân cách của Linh hồn Thay thế Bóng tối <a class="header-anchor" href="#_2-quyen-nhan-cach-cua-linh-hon-thay-the-bong-toi" aria-label="Permalink to &quot;(2) Quyền Nhân cách của Linh hồn Thay thế Bóng tối&quot;">​</a></h3><p>Việc công nhận quyền nhân cách của linh hồn thay thế bóng tối tương đối phức tạp, nguyên tắc này lấy lập trường &quot;công nhận hạn chế&quot;:</p><table tabindex="0"><thead><tr><th>Giai đoạn phát triển</th><th>Công nhận quyền nhân cách</th><th>Phạm vi quyền</th></tr></thead><tbody><tr><td>Giai đoạn ăn mòn năng lượng (giai đoạn thứ nhất)</td><td>Không có nhân cách độc lập</td><td>Chưa hình thành linh hồn độc lập, không có quyền nhân cách độc lập</td></tr><tr><td>Giai đoạn ô nhiễm linh hồn (giai đoạn thứ hai)</td><td>Không có nhân cách độc lập</td><td>Vẫn là trạng thái ô nhiễm của linh hồn chủ nhà ban đầu, không có quyền nhân cách độc lập</td></tr><tr><td>Giai đoạn hình thành song hồn (giai đoạn thứ ba)</td><td>Quyền nhân cách hạn chế</td><td>Có ý thức độc lập sơ bộ, hưởng thụ quyền phẩm giá linh hồn cơ bản, nhưng không hưởng thụ quyền kiểm soát cơ thể và quyền công dân đầy đủ</td></tr><tr><td>Giai đoạn bóng tối chủ đạo (giai đoạn thứ tư)</td><td>Quyền nhân cách hạn chế</td><td>Có ý thức độc lập đầy đủ, hưởng thụ quyền phẩm giá linh hồn và quyền được đối xử với sự tôn trọng, nhưng do tính nguy hiểm của nó, quyền bị hạn chế cần thiết</td></tr><tr><td>Giai đoạn thay thế hoàn toàn (giai đoạn thứ năm)</td><td>Quyền nhân cách đầy đủ (nhưng là sự tồn tại thù địch)</td><td>Chủ nhà ban đầu đã diệt vong, linh hồn bóng tối trở thành linh hồn duy nhất của cơ thể, có quyền nhân cách đầy đủ, nhưng do hành vi thù địch của nó, có thể áp dụng các biện pháp cưỡng chế bao gồm cả tiêu diệt theo pháp luật</td></tr></tbody></table><h3 id="_3-noi-dung-cu-the-cua-quyen-nhan-cach-han-che" tabindex="-1">(3) Nội dung Cụ thể của Quyền Nhân cách Hạn chế <a class="header-anchor" href="#_3-noi-dung-cu-the-cua-quyen-nhan-cach-han-che" aria-label="Permalink to &quot;(3) Nội dung Cụ thể của Quyền Nhân cách Hạn chế&quot;">​</a></h3><p>Quyền nhân cách hạn chế mà linh hồn thay thế bóng tối hưởng thụ ở giai đoạn thứ ba và thứ tư bao gồm:</p><ol><li><strong>Quyền phẩm giá linh hồn</strong>: Không được đối xử bằng cách xúc phạm, ngược đãi, tra tấn, ngay cả trong kiểm soát và xử lý cũng phải duy trì sự tôn trọng cơ bản.</li><li><strong>Quyền tiêu diệt không đau đớn</strong>: Nếu cuối cùng quyết định tiêu diệt linh hồn thay thế bóng tối, nên áp dụng phương pháp không đau đớn, nhanh chóng để giảm bớt đau khổ của nó.</li><li><strong>Quyền bày tỏ</strong>: Trong điều kiện an toàn và có thể kiểm soát, linh hồn thay thế bóng tối có quyền bày tỏ ý chí và lập trường của mình, nhưng sự bày tỏ của nó không có ràng buộc pháp lý.</li><li><strong>Quyền được lắng nghe</strong>: Khi đưa ra các quyết định quan trọng liên quan đến linh hồn thay thế bóng tối, nên lắng nghe ý kiến của nó trong giới hạn hợp lý.</li></ol><p>Linh hồn thay thế bóng tối không hưởng thụ các quyền sau: quyền kiểm soát cơ thể, quyền tự do hành động, quyền chính trị công dân, quyền sở hữu tài sản (tài sản của chủ nhà ban đầu thuộc về chủ nhà ban đầu), quyền sinh sản (để ngăn chặn sự lan truyền của dòng máu bóng tối).</p><h2 id="_4-quy-tac-can-bang-xung-đot-loi-ich-song-hon" tabindex="-1">4. Quy tắc Cân bằng Xung đột Lợi ích Song hồn <a class="header-anchor" href="#_4-quy-tac-can-bang-xung-đot-loi-ich-song-hon" aria-label="Permalink to &quot;4. Quy tắc Cân bằng Xung đột Lợi ích Song hồn&quot;">​</a></h2><p>Khi lợi ích của linh hồn chủ nhà ban đầu và linh hồn thay thế bóng tối xung đột, cân bằng được thực hiện theo các quy tắc sau:</p><h3 id="_1-loai-xung-đot-va-quy-tac-can-bang" tabindex="-1">(1) Loại Xung đột và Quy tắc Cân bằng <a class="header-anchor" href="#_1-loai-xung-đot-va-quy-tac-can-bang" aria-label="Permalink to &quot;(1) Loại Xung đột và Quy tắc Cân bằng&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Loại xung đột</th><th>Quy tắc cân bằng</th></tr></thead><tbody><tr><td>Xung đột quyền sống (sự sống của một bên có điều kiện là sự diệt vong của bên kia)</td><td>Quyền sống của linh hồn chủ nhà ban đầu được ưu tiên, trong điều kiện không thể cùng tồn tại, ưu tiên bảo vệ sự sống của chủ nhà ban đầu</td></tr><tr><td>Xung đột quyền kiểm soát cơ thể</td><td>Linh hồn chủ nhà ban đầu có quyền kiểm soát cuối cùng đối với cơ thể, quyền kiểm soát cơ thể của linh hồn bóng tối bị hạn chế nghiêm ngặt</td></tr><tr><td>Xung đột quyền bày tỏ</td><td>Sự bày tỏ của linh hồn chủ nhà ban đầu có ràng buộc pháp lý, sự bày tỏ của linh hồn bóng tối chỉ làm tham khảo</td></tr><tr><td>Xung đột quyền tài sản</td><td>Cơ thể và tài sản thuộc về chủ nhà ban đầu, linh hồn bóng tối không có quyền tài sản</td></tr><tr><td>Xung đột quyền lựa chọn điều trị</td><td>Linh hồn chủ nhà ban đầu có quyền lựa chọn có接受 điều trị thanh lọc hay không, linh hồn bóng tối không có quyền ngăn cản</td></tr><tr><td>Xung đột cách thức xử lý</td><td>Trong xử lý liên quan đến tiêu diệt linh hồn bóng tối, ý chí của linh hồn chủ nhà ban đầu có vai trò quyết định (nhưng phải经过 xét duyệt đạo đức)</td></tr></tbody></table><h3 id="_2-su-ton-trong-va-han-che-đoi-voi-y-chi-chu-nha-ban-đau" tabindex="-1">(2) Sự Tôn trọng và Hạn chế đối với Ý chí Chủ nhà Ban đầu <a class="header-anchor" href="#_2-su-ton-trong-va-han-che-đoi-voi-y-chi-chu-nha-ban-đau" aria-label="Permalink to &quot;(2) Sự Tôn trọng và Hạn chế đối với Ý chí Chủ nhà Ban đầu&quot;">​</a></h3><p>Trong điều kiện linh hồn chủ nhà ban đầu có thể bày tỏ ý chí, nên tôn trọng đầy đủ ý chí của chủ nhà ban đầu, nhưng các trường hợp sau là ngoại lệ:</p><ol><li>Ý chí của chủ nhà ban đầu rõ ràng gây hại cho an toàn công cộng hoặc quyền lợi hợp pháp của người khác thì không được bảo vệ.</li><li>Việc bày tỏ ý chí không chân thực do chủ nhà ban đầu thực hiện dưới ảnh hưởng của linh hồn bóng tối không có hiệu lực pháp lý.</li><li>Chủ nhà ban đầu tự nguyện lựa chọn dung hợp với linh hồn bóng tối thì phải经过 xét duyệt đạo đức nghiêm ngặt và đánh giá rủi ro, xác nhận sự tồn tại sau dung hợp sẽ không构成 mối đe dọa cho xã hội.</li><li>Chủ nhà ban đầu tự nguyện lựa chọn từ bỏ điều trị, chấp nhận thay thế hoàn toàn bởi linh hồn bóng tối thì xã hội nên can thiệp và khuyến khích, nhưng trong điều kiện chủ nhà ban đầu hoàn toàn tỉnh táo và xác nhận lặp lại, cuối cùng nên tôn trọng quyền tự quyết của chủ nhà ban đầu (đây là vùng xám đạo đức, cần xét duyệt từng trường hợp).</li></ol><h2 id="_5-co-che-xet-duyet-đao-đuc-song-hon" tabindex="-1">5. Cơ chế Xét duyệt Đạo đức Song hồn <a class="header-anchor" href="#_5-co-che-xet-duyet-đao-đuc-song-hon" aria-label="Permalink to &quot;5. Cơ chế Xét duyệt Đạo đức Song hồn&quot;">​</a></h2><p>Để đảm bảo việc xử lý vấn đề song hồn phù hợp với nguyên tắc đạo đức, nhà nước thiết lập cơ chế xét duyệt đạo đức song hồn:</p><h3 id="_1-uy-ban-xet-duyet-đao-đuc" tabindex="-1">(1) Ủy ban Xét duyệt Đạo đức <a class="header-anchor" href="#_1-uy-ban-xet-duyet-đao-đuc" aria-label="Permalink to &quot;(1) Ủy ban Xét duyệt Đạo đức&quot;">​</a></h3><ul><li><strong>Thành phần</strong>: Bao gồm các nhà đạo đức học, nhà pháp luật, nhà khoa học sự sống, người tu luyện, đại diện chủng tộc nước ngoài, đại diện công chúng xã hội, trong đó các chuyên gia có kinh nghiệm nghiên cứu hoặc điều trị cơ thể thay thế bóng tối không ít hơn một phần ba.</li><li><strong>Trách nhiệm</strong>: Xét duyệt và phán quyết các vấn đề đạo đức quan trọng liên quan đến song hồn, bao gồm quyết định tiêu diệt linh hồn bóng tối, phê duyệt dung hợp song hồn, công nhận hiệu lực của ý chí chủ nhà ban đầu, v.v.</li><li><strong>Tính độc lập</strong>: Ủy ban xét duyệt đạo đức thực thi quyền hạn một cách độc lập, không bị can thiệp bởi cơ quan hành chính và cá nhân.</li><li><strong>Thủ tục</strong>: Xét duyệt thực hiện chế độ điều trần, đưa ra phán quyết sau khi lắng nghe ý kiến của tất cả các bên như chủ nhà ban đầu (nếu có thể bày tỏ), đội ngũ điều trị, gia đình, đại diện xã hội, v.v.</li></ul><h3 id="_2-cac-hang-muc-phai经过-xet-duyet-đao-đuc" tabindex="-1">(2) Các Hạng mục Phải经过 Xét duyệt Đạo đức <a class="header-anchor" href="#_2-cac-hang-muc-phai经过-xet-duyet-đao-đuc" aria-label="Permalink to &quot;(2) Các Hạng mục Phải经过 Xét duyệt Đạo đức&quot;">​</a></h3><p>Các hạng mục sau chỉ có thể thực hiện sau khi经过 xét duyệt và phê duyệt của ủy ban xét duyệt đạo đức song hồn:</p><ol><li>Thực hiện xử lý tiêu diệt linh hồn bóng tối đối với cơ thể thay thế bóng tối ở giai đoạn thứ ba và thứ tư.</li><li>Thực hiện phẫu thuật dung hợp song hồn đối với cơ thể thay thế bóng tối.</li><li>Thực hiện phẫu thuật tách rời linh hồn đối với cơ thể thay thế bóng tối.</li><li>Đưa ra quyết định xử lý cuối cùng đối với cơ thể thay thế bóng tối mà ý chí của chủ nhà ban đầu là từ bỏ điều trị.</li><li>Thực hiện kế hoạch điều trị đối với cơ thể thay thế bóng tối có thể gây ra tổn thương cho linh hồn chủ nhà ban đầu.</li><li>Thực hiện nghiên cứu khoa học liên quan đến linh hồn đối với cơ thể thay thế bóng tối.</li><li>Các hạng mục khác liên quan đến vấn đề đạo đức quan trọng của song hồn.</li></ol><h2 id="_6-quyen-va-nghia-vu-xa-hoi-cua-co-the-song-hon" tabindex="-1">6. Quyền và Nghĩa vụ Xã hội của Cơ thể Song hồn <a class="header-anchor" href="#_6-quyen-va-nghia-vu-xa-hoi-cua-co-the-song-hon" aria-label="Permalink to &quot;6. Quyền và Nghĩa vụ Xã hội của Cơ thể Song hồn&quot;">​</a></h2><h3 id="_1-quyen-xa-hoi" tabindex="-1">(1) Quyền Xã hội <a class="header-anchor" href="#_1-quyen-xa-hoi" aria-label="Permalink to &quot;(1) Quyền Xã hội&quot;">​</a></h3><p>Trong điều kiện linh hồn chủ nhà ban đầu vẫn còn tồn tại, cơ thể song hồn (cơ thể thay thế bóng tối) hưởng thụ các quyền xã hội sau:</p><ol><li>Quyền nhận được bảo đảm sống cơ bản và điều trị y tế.</li><li>Quyền nhận được hỗ trợ pháp lý và tư vấn đạo đức.</li><li>Quyền tiếp xúc với bạn bè và người thân trong điều kiện an toàn và có thể kiểm soát.</li><li>Quyền nhận được giáo dục và hoạt động văn hóa (trong cơ sở cách ly).</li><li>Quyền khiếu nại và xem xét lại đối với quyết định xử lý.</li></ol><h3 id="_2-nghia-vu-va-han-che-xa-hoi" tabindex="-1">(2) Nghĩa vụ và Hạn chế Xã hội <a class="header-anchor" href="#_2-nghia-vu-va-han-che-xa-hoi" aria-label="Permalink to &quot;(2) Nghĩa vụ và Hạn chế Xã hội&quot;">​</a></h3><p>Cơ thể song hồn đồng時承担 các nghĩa vụ và hạn chế sau:</p><ol><li>Nghĩa vụ接受 kiểm soát cách ly và điều trị.</li><li>Nghĩa vụ không tấn công hoặc lây nhiễm các sinh vật khác (người vi phạm sẽ chịu kiểm soát nghiêm ngặt hơn).</li><li>Nghĩa vụ phối hợp đánh giá nhận dạng và giám sát.</li><li>Tự do hành động bị hạn chế nghiêm ngặt, không được rời khỏi cơ sở cách ly trước khi khỏi bệnh.</li><li>Không được tham gia vào các hoạt động có thể làm trầm trọng thêm sự thay thế như tu luyện, lan truyền năng lượng bóng tối, v.v.</li></ol><h2 id="_7-tranh-cai-tien-tuyen-cua-đao-đuc-song-hon" tabindex="-1">7. Tranh cãi Tiền tuyến của Đạo đức Song hồn <a class="header-anchor" href="#_7-tranh-cai-tien-tuyen-cua-đao-đuc-song-hon" aria-label="Permalink to &quot;7. Tranh cãi Tiền tuyến của Đạo đức Song hồn&quot;">​</a></h2><p>Trong lĩnh vực đạo đức song hồn vẫn còn một số tranh cãi tiền tuyến chưa đạt được đồng thuận, cần tiếp tục khám phá trong thực tiễn:</p><ol><li><strong>Vấn đề &quot;tội nguyên tổ&quot; của linh hồn bóng tối</strong>: Linh hồn thay thế bóng tối từ khi sinh ra đã có tính phá hủy, điều này có nghĩa là nó bẩm sinh là &quot;ác&quot; không? Có khả năng tồn tại linh hồn bóng tối &quot;lành&quot; không?</li><li><strong>Tính chính đáng đạo đức của dung hợp linh hồn</strong>: Linh hồn mới được sinh ra từ dung hợp song hồn không phải là chủ nhà ban đầu cũng không phải là linh hồn bóng tối, địa vị đạo đức của &quot;sự tồn tại thứ ba&quot; này được công nhận như thế nào?</li><li><strong>Giới hạn đầu tư nguồn lực</strong>: Xã hội nên đầu tư bao nhiêu nguồn lực để cứu linh hồn chủ nhà ban đầu trong cơ thể thay thế bóng tối? Khi chi phí cứu vớt cực kỳ cao và tỷ lệ thành công cực kỳ thấp, có vẫn còn nghĩa vụ cố gắng cứu vớt tối đa không?</li><li><strong>Khả năng cải tạo linh hồn bóng tối</strong>: Có thể cải tạo linh hồn bóng tối thành sự tồn tại không phá hủy thông qua giáo dục, cảm hóa, cải tạo năng lượng, v.v. không? Nếu có thể, linh hồn bóng tối sau cải tạo có nên được hưởng quyền nhân cách đầy đủ không?</li><li><strong>Cân bằng giữa phòng ngừa và quyền riêng tư</strong>: Để phòng ngừa sự phát sinh của cơ thể thay thế bóng tối, có thể giám sát sự tiếp xúc của sinh vật với năng lượng vực thẳm không? Việc giám sát này có xâm phạm quyền riêng tư của linh hồn không?</li></ol><p>Những vấn đề tranh cãi này được các cơ quan nghiên cứu đạo đức song hồn tiếp tục nghiên cứu, ủy ban xét duyệt đạo đức đưa ra phán quyết trong từng trường hợp cụ thể theo tình hình cụ thể, các kết luận liên quan sẽ tiếp tục cập nhật nguyên tắc này.</p><h2 id="loi-ket" tabindex="-1">Lời kết <a class="header-anchor" href="#loi-ket" aria-label="Permalink to &quot;Lời kết&quot;">​</a></h2><p>Nguyên tắc đạo đức song hồn là sự thể hiện sâu sắc của đạo đức sự sống của nền văn minh Cộng sinh Mỏ neo. Bằng cách thiết lập các nguyên tắc cơ bản như phẩm giá linh hồn, ưu tiên chủ nhà ban đầu, thiệt hại tối thiểu, công nhận ranh giới quyền nhân cách của song hồn, thiết lập quy tắc cân bằng xung đột lợi ích và cơ chế xét duyệt đạo đức, nó cung cấp cơ sở đạo đức vững chắc cho việc quản trị cơ thể thay thế bóng tối. Tinh thần cốt lõi của đạo đức song hồn là: ngay cả khi đối mặt với kẻ thù nguy hiểm nhất, cũng không từ bỏ sự kiên định với phẩm giá của sự sống; ngay cả dưới mối đe dọa an toàn khẩn cấp nhất, cũng không vượt qua đường cùng của đạo đức. Đây chính là dấu hiệu cơ bản phân biệt nền văn minh cộng sinh với nền văn minh cướp đoạt.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>57-Nguồn gốc và Bản chất của Cơ thể Thay thế Bóng tối</li><li>59-Xử lý Bốn nhánh của Cơ thể Thay thế Bóng tối</li><li>48-Hệ thống Tư pháp và Cơ chế Phán quyết</li><li>40-Nguyên tắc Tổng thể Hiến pháp Cộng sinh</li></ul>',50)])])}const e=h(a,[["render",g]]);export{d as __pageData,e as default};
